// Master orchestrator: determines which pipeline step to run
const input = $input.first().json;
const body = input.body || input;

const validSteps = [
  'full_pipeline',
  'data_collection',
  'content_optimization',
  'monitoring',
  'keyword_gap',
  'position_check',
  'site_audit'
];

const config = {
  step: body.step || 'full_pipeline',
  domain: body.domain || 'kahunaworkforce.com',
  ga4_property_id: body.ga4_property_id || '',
  gsc_site_url: body.gsc_site_url || 'https://kahunaworkforce.com/',
  semrush_api_key: body.semrush_api_key || '',
  anthropic_api_key: body.anthropic_api_key || '',
  database: body.database || 'us',
  page_url: body.page_url || '',
  target_keywords: body.target_keywords || [],
  competitors: body.competitors || [],
  top_n_pages: body.top_n_pages || 20,
  date_range_days: body.date_range_days || 90
};

if (!validSteps.includes(config.step)) {
  return [{ json: { error: true, message: `Invalid step '${config.step}'. Valid: ${validSteps.join(', ')}` } }];
}

return [{ json: config }];

// For ad-hoc quick actions: keyword gap, position check, site audit
const config = $('Route Pipeline Step').first().json;
const step = config.step;

const apiCalls = {
  keyword_gap: {
    url: `https://api.semrush.com/?type=domain_domains&key=${config.semrush_api_key}&display_limit=50&domains=${config.domain}|${(config.competitors || []).join('|')}&database=${config.database}&export_columns=Ph,P0,P1,P2,P3,P4,Nr,Td,In`,
    description: 'Keyword gap analysis against competitors'
  },
  position_check: {
    url: `https://api.semrush.com/?type=domain_organic&key=${config.semrush_api_key}&display_limit=50&domain=${config.domain}&database=${config.database}&export_columns=Ph,Po,Pp,Nq,Kd,Tr,Ur&display_sort=tr_desc`,
    description: 'Current SERP positions for top keywords'
  },
  site_audit: {
    url: `https://api.semrush.com/?type=domain_ranks&key=${config.semrush_api_key}&domain=${config.domain}&database=${config.database}&export_columns=Dn,Rk,Or,Ot,Oc,Ad,At,Ac`,
    description: 'Domain health and ranking overview'
  },
  full_pipeline: {
    url: '',
    description: 'Full pipeline runs data_collection → content_optimization → monitoring sequentially'
  }
};

const call = apiCalls[step];
if (!call) {
  return [{ json: { error: true, message: `Step '${step}' should be routed to a sub-workflow` } }];
}

return [{ json: { ...config, api_url: call.url, step_description: call.description } }];

// Format ad-hoc response
const config = $('Ad-hoc API Call').first().json;
const raw = $('Execute Ad-hoc Call').first().json;

let parsed = raw;
try {
  if (typeof raw === 'string' || raw.data) {
    const csvText = typeof raw === 'string' ? raw : raw.data;
    const lines = csvText.split('\n').filter(l => l.trim());
    if (lines.length > 1) {
      const headers = lines[0].split(';');
      parsed = lines.slice(1).map(line => {
        const vals = line.split(';');
        const obj = {};
        headers.forEach((h, i) => { obj[h.trim()] = vals[i]?.trim() || ''; });
        return obj;
      });
    }
  }
} catch(e) { parsed = raw; }

return [{
  json: {
    step: config.step,
    step_description: config.step_description,
    domain: config.domain,
    generated_at: new Date().toISOString(),
    results: parsed
  }
}];
